package uz.mirix.tracelens.internal;
import uz.mirix.tracelens.TraceLensProperties; import java.net.URI; import java.util.Locale;
final class HttpClientSupport { private HttpClientSupport(){} static String label(String method,URI uri,TraceLensProperties p){ String host=uri.getHost(); if(host==null||host.isBlank())host=uri.getAuthority(); if(host==null||host.isBlank())host="<unknown-host>"; StringBuilder v=new StringBuilder("HTTP ").append(method.toUpperCase(Locale.ROOT)).append(' ').append(host); if(p.getHttpClient().isIncludePath())v.append(safePath(uri.getPath())); return SafeText.singleLine(v.toString(),180);} private static String safePath(String path){if(path==null||path.isBlank()||"/".equals(path))return ""; return path.replaceAll("/\\d+(?=/|$)","/{id}").replaceAll("(?i)/[0-9a-f]{8}-[0-9a-f-]{27,36}(?=/|$)","/{id}");}}
